"""Independent browser projection of native relational field records."""
HTML=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PLN Chess · Relative fields</title><style>
:root{color-scheme:dark;--bg:#101923;--panel:#182532;--line:#344656;--ink:#e6edf4;--muted:#abbfce;--accent:#8fdbc8;--unknown:#a5aabe;--yes:#70d2ba;--no:#efa585;--pending:#ebca7f}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui,sans-serif}main{max-width:1250px;margin:auto;padding:28px}a{color:var(--accent)}header{display:flex;align-items:start;justify-content:space-between;gap:20px}h1{font-size:32px;line-height:1.2;margin:6px 0 14px}h2{font-size:18px;margin:0 0 14px}p{margin:8px 0;color:var(--muted)}.eyebrow{text-transform:uppercase;letter-spacing:.14em;font-size:12px;color:var(--accent)}.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:20px;margin-top:20px;min-width:0}.controls{display:grid;grid-template-columns:2fr 1fr 1fr;gap:14px}.wide{grid-column:1/-1}label{display:flex;flex-direction:column;gap:5px;color:var(--muted);font-size:13px}input,select,textarea,button{font:inherit;color:var(--ink);border:1px solid #546777;background:#111c27;border-radius:6px;padding:9px 10px;min-width:0;max-width:100%}textarea{resize:vertical}button{cursor:pointer}button:hover{border-color:var(--accent)}button:disabled{opacity:.5;cursor:wait}.primary{background:var(--accent);color:#112b29;font-weight:700;border:0}.actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.status{font-family:ui-monospace,monospace;font-size:13px}.boards{display:grid;grid-template-columns:1fr 1fr;gap:22px}.board{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));aspect-ratio:1;max-width:420px;border:2px solid #657b8e;margin:auto}.cell{position:relative;display:flex;justify-content:center;align-items:center;aspect-ratio:1;padding:0;border:0;border-radius:0;color:#f8fafc;background:#496072;font-size:clamp(20px,3.4vw,38px);text-shadow:1px 1px 2px #05090c}.cell.dark{background:#243949}.cell.selected{outline:3px solid #eecb7c;outline-offset:-3px}.cell small{position:absolute;left:3px;bottom:0;font:10px system-ui;color:#d2e1e9;text-shadow:none}.cell.supported{box-shadow:inset 0 0 0 4px var(--yes)}.cell.contradicted{box-shadow:inset 0 0 0 3px var(--no)}.cell.unknown{box-shadow:inset 0 0 0 2px var(--unknown)}.cell.incomplete{box-shadow:inset 0 0 0 3px var(--pending)}.legend{display:flex;gap:15px;flex-wrap:wrap;font-size:12px}.legend span:before{content:'● ';color:var(--tone)}.table-wrap{overflow:auto;max-height:490px;border:1px solid var(--line);border-radius:6px}table{border-collapse:collapse;width:100%;font-size:13px;white-space:nowrap}th,td{text-align:left;padding:9px 12px;border-bottom:1px solid var(--line)}th{position:sticky;top:0;background:#233444;z-index:1}td button{padding:3px 9px}.supported{color:var(--yes)}.contradicted{color:var(--no)}.unknown{color:var(--unknown)}.incomplete{color:var(--pending)}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:480px;overflow:auto;font-size:12px;background:#101923;padding:14px;border-radius:6px}.facts{display:flex;gap:22px;flex-wrap:wrap;font-size:13px}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.badge{border:1px solid var(--line);border-radius:20px;padding:4px 10px;font-size:12px;color:var(--muted)}:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
@media(max-width:700px){main{padding:16px}header{display:block}h1{font-size:27px}.controls{grid-template-columns:1fr 1fr}.controls label:first-child{grid-column:1/-1}.boards,.detail-grid{grid-template-columns:1fr}.panel{padding:14px}.cell{font-size:32px}.table-wrap{max-height:360px}.board{width:100%}header a{display:inline-block;margin-top:10px}}
</style></head><body><main><header><div><div class="eyebrow">PLN Chess · Cycle 11</div><h1>Relative influence fields</h1><p>Inspect learned relations around a piece and follow their native evidence through a proposed move.</p></div><a href="/">Legal move inspector ↗</a></header>
<form id="field-form" class="panel"><div class="controls">
<label>Worked example<select id="field-example"></select></label><label>Field checkpoint<select id="field-model"><option value="trained">Learned conditionals</option><option value="empty">Empty · no evidence</option></select></label>
<label>Field family<select id="field-family"><option value="all">All four fields</option><option value="attack">Attack</option><option value="defense">Defense</option><option value="mobility">Mobility</option><option value="king-exposure">King exposure</option><option value="geometry">Empty-board geometry</option></select></label>
<label class="wide">Supplied position · FEN<input id="field-fen" required spellcheck="false"></label>
<label>Source piece square · blank selects all<input id="field-piece" placeholder="a4" spellcheck="false"></label><label>Proposed move · UCI<input id="field-move" placeholder="d4f5" spellcheck="false"></label><label>Native proof-node budget<input id="field-budget" type="number" min="0" max="1000000" value="100000" required></label>
<label>Unknown cells · comma separated<input id="field-unknown" placeholder="d4" spellcheck="false"></label><label>Legal proof mode<select id="field-legal-mode"><option value="operational">Operational</option><option value="strict">Strict</option><option value="experimental">Experimental</option></select></label>
<details class="wide"><summary>Supplied history and provenance</summary><p>Optional event input or a verified temporal transport receipt. An empty history leaves historical claims unattested.</p><textarea id="field-history" rows="4" style="width:100%" aria-label="Supplied history JSON"></textarea></details>
<div class="wide actions"><button class="primary" id="field-run" type="submit">Build fields</button><button id="field-export" type="button" disabled>Export proof package</button><span id="field-status" class="status" role="status" aria-live="polite">Loading examples…</span></div></div>
<p id="field-description"></p></form>
<section class="panel"><h2>Before and hypothetical successor</h2><div class="facts"><span id="field-candidate-status">Candidate not evaluated</span><span class="badge">No strategic score or move ranking</span></div><p>Outlines show separate relation classifications for the selected family and source. Multiple relations remain separate in the table. Strength and confidence are not board intensities.</p>
<div class="legend"><span style="--tone:var(--yes)">supported</span><span style="--tone:var(--no)">contradicted</span><span style="--tone:var(--unknown)">unknown</span><span style="--tone:var(--pending)">incomplete</span></div>
<div class="boards"><div><h3>Before</h3><div id="field-before" class="board" aria-label="Before board"></div></div><div><h3>Hypothetical successor</h3><div id="field-after" class="board" aria-label="Hypothetical successor board"></div></div></div><p id="field-costs" class="status"></p></section>
<section class="panel"><h2>Relative relations</h2><p>Defense means influence on a friendly occupied cell. It does not prove a legal recapture. King exposure records local threats; it does not prove universal safety.</p><div class="table-wrap"><table id="field-relations"><thead><tr><th>State</th><th>Family</th><th>From → target</th><th>Relative offset</th><th>Classification</th><th>Strength</th><th>Confidence</th><th>Evidence</th></tr></thead><tbody></tbody></table></div></section>
<div class="detail-grid"><section class="panel"><h2>Typed differences</h2><p>Comparisons of before/after proofs are host diagnostics. Each change has no native truth value; an absent edge does not mean false.</p><div id="field-differences">Build a candidate comparison to inspect changes.</div></section><section class="panel"><h2>Selected native proof</h2><p>Inspect the matched relative rule, evidence IDs, observed premises, and executed native operators.</p><pre id="field-proof">Select a relation’s proof.</pre></section></div>
<footer class="panel"><p>These are experimental local conditional fields. No conjunction introduction, global legality theorem, independent-defender aggregation, calibrated strategic value, or chess-playing competence is asserted.</p></footer>
</main><script>
const $=id=>document.getElementById(id);let catalog=[],result=null;const symbols={White:{King:'♔',Queen:'♕',Rook:'♖',Bishop:'♗',Knight:'♘',Pawn:'♙'},Black:{King:'♚',Queen:'♛',Rook:'♜',Bishop:'♝',Knight:'♞',Pawn:'♟'}};
function square(p){return String.fromCharCode(97+p[0])+(p[1]+1)}
function example(){const e=catalog.find(x=>x.id===$('field-example').value);if(!e)return;$('field-fen').value=e.fen;$('field-move').value=e.move;$('field-piece').value=e.selected_piece_square||'';$('field-family').value='all';$('field-unknown').value=(e.unknown_squares||[]).map(square).join(',');$('field-history').value=e.history_input?JSON.stringify(e.history_input,null,2):'';$('field-description').textContent=e.description||''}
function board(id,state){const box=$(id);box.replaceChildren();for(let y=7;y>=0;y--)for(let x=0;x<8;x++){const name=square([x,y]);const cell=document.createElement('button');cell.type='button';cell.className='cell'+((x+y)%2===0?' dark':'');const p=state?.pieces.find(p=>p.square[0]===x&&p.square[1]===y);const unknown=state?.unknown_squares.some(s=>s[0]===x&&s[1]===y);cell.append(document.createTextNode(unknown?'?':p?symbols[p.owner][p.kind]:''));const label=document.createElement('small');label.textContent=name;cell.append(label);const relations=state?.relations.filter(r=>r.target_square===name)||[];if(relations.length===1)cell.classList.add(relations[0].classification);if(p&&state.selected_source_entities.includes(p.id))cell.classList.add('selected');cell.title=name+(p?' '+p.owner+' '+p.kind:'')+(unknown?' · unknown contents':'')+' · '+relations.length+' separate relations';cell.setAttribute('aria-label',cell.title);cell.onclick=()=>{if(relations.length===1)showProof(relations[0]);else if(p){$('field-piece').value=name;$('field-status').textContent='Source selected. Build fields to refresh.'}};box.append(cell)}}
function showProof(r){$('field-proof').textContent=JSON.stringify(r,null,2)}
function render(data){const before=data.before||data;const after=data.after||null;board('field-before',before);board('field-after',after);$('field-candidate-status').textContent=data.candidate?'Candidate '+data.candidate.move+' · '+data.candidate.classification+' · successor remains hypothetical':'No candidate · supplied snapshot only';const rows=$('field-relations').querySelector('tbody');rows.replaceChildren();for(const [side,state] of [['before',before],['after',after]]){if(!state)continue;for(const r of state.relations){const tr=document.createElement('tr');for(const value of [side,r.family,r.source_square+' → '+r.target_square,r.relative_displacement.join(', '),r.classification,r.raw_stv.strength.toFixed(4),r.raw_stv.confidence.toFixed(4)]){const td=document.createElement('td');td.textContent=value;if(value===r.classification)td.className=r.classification;tr.append(td)}const td=document.createElement('td');const button=document.createElement('button');button.textContent=r.proof_trace.length?'Native proof':'Why unknown';button.dataset.native=String(r.proof_trace.length>0);button.onclick=()=>showProof(r);td.append(button);tr.append(td);rows.append(tr)}}
const delta=$('field-differences');delta.replaceChildren();const changes=data.differences||[];const intro=document.createElement('p');intro.textContent=changes.length+' changed relations · change truth values: none';delta.append(intro);const list=document.createElement('ul');for(const d of changes.slice(0,30)){const li=document.createElement('li');const r=d.after||d.before;li.textContent=d.family+' '+r.source_square+' → '+r.target_square+': '+d.transition;list.append(li)}delta.append(list);if(changes.length>30){const p=document.createElement('p');p.textContent='The export contains all '+changes.length+' differences.';delta.append(p)}$('field-proof').textContent='Select a relation’s proof.';
const states=[before,after].filter(Boolean);$('field-costs').textContent=states.map((s,i)=>(i?'After':'Before')+': '+s.execution.native_invocations+' executed native operators · '+s.execution.relation_cache_hits+' reused relations · '+s.execution.elapsed_seconds.toFixed(2)+' s').join(' | ');$('field-status').textContent=states.some(s=>s.execution.truncated)?'Incomplete · inspect budgets and gaps':'Complete · conditional scope only';$('field-export').disabled=false}
$('field-example').onchange=example;$('field-form').onsubmit=async event=>{event.preventDefault();$('field-run').disabled=true;$('field-status').textContent='Computing native conditionals…';try{const payload={fen:$('field-fen').value,model:$('field-model').value,family:$('field-family').value,piece:$('field-piece').value.trim(),candidate:$('field-move').value.trim(),unknown_squares:$('field-unknown').value.split(',').map(s=>s.trim()).filter(Boolean),history:$('field-history').value.trim()?JSON.parse($('field-history').value):null,legal_mode:$('field-legal-mode').value,max_invocations:Number($('field-budget').value)};const response=await fetch('/cycle11-fields',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw Error(data.error||'Request failed');result=data;render(data)}catch(error){$('field-status').textContent='Error: '+error.message}finally{$('field-run').disabled=false}};
$('field-export').onclick=()=>{if(!result)return;const blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='pln-relative-fields.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
board('field-before',null);board('field-after',null);fetch('/cycle11-field-catalog').then(r=>{if(!r.ok)throw Error('Examples unavailable');return r.json()}).then(data=>{catalog=data.examples;for(const e of catalog){const o=document.createElement('option');o.value=e.id;o.textContent=e.id.replaceAll('-',' ');$('field-example').append(o)}example();$('field-status').textContent='Ready · choose a field and build'}).catch(error=>{$('field-status').textContent='Error: '+error.message});
</script></body></html>'''
